using System;
using UnityEngine;
using UnityEngine.InputSystem;
using LWS.TruckSports;
namespace LWS.TruckBowling {
[DefaultExecutionOrder(-100)]public sealed class BowlingMatch:MonoBehaviour {
 public const string SetupKey="TruckBowling.Setup.v1";public BowlingSetup setup=new BowlingSetup();public BowlingLane[] lanes;public BowlingMenus menus;public SportsSettings settings;public SportsFeedback feedback;public AudioListener listener;
 public bool InMatch{get;private set;}public bool Paused{get;private set;}public bool Finished{get;private set;}public int ActiveSlot{get;private set;}public int ModalOwner{get;private set;}public int SetupVersion{get;private set;}public int[] Winners{get;private set;}=Array.Empty<int>();
 static readonly BowlingPlayer sharedKeys=new BowlingPlayer{forward=Key.W,left=Key.A,back=Key.S,right=Key.D};BowlingPlayer Keys(int slot)=>setup.mode==BowlingMode.HotSeat&&setup.sharedHotSeat?sharedKeys:setup.players[slot];
 readonly SportsDeviceInput input=new SportsDeviceInput();float handoffTimer;bool handoff;int menuGateFrame;bool menuReleased;
 public bool AllAI{get{for(int i=0;i<setup.count;i++)if(setup.players[i].source!=BowlingSource.AI)return false;return true;}}
 public bool Ready(int slot){var p=setup.players[slot];return p.source==BowlingSource.AI||p.source==BowlingSource.Keyboard&&Keyboard.current!=null&&Keyboard.current.enabled||p.Controller&&p.pad!=null&&p.pad.added&&p.pad.enabled;}
 public bool DevicesReady{get{if(!setup.Validate(out _))return false;for(int i=0;i<setup.count;i++)if(!Ready(i))return false;return true;}}
 void Awake(){try{if(LWS.TruckSports.SportsPrefs.HasKey(SetupKey)){var saved=JsonUtility.FromJson<BowlingSetup>(LWS.TruckSports.SportsPrefs.GetString(SetupKey));if(saved!=null&&saved.players!=null&&saved.players.Length==8){setup=saved;setup.count=Mathf.Clamp(setup.count,1,setup.mode==BowlingMode.HotSeat?8:4);}}}catch(Exception){Debug.LogWarning("Bowling setup invalid; using safe defaults.");}}
 void Start(){foreach(var lane in lanes){lane.truck.Clear();foreach(var p in lane.pins)p.Freeze();lane.cab.view.enabled=lane.index==0;}Layout();menus.Show(BowlingScreen.Setup);}
 void OnEnable(){InputSystem.onDeviceChange+=DeviceChanged;}void OnDisable(){InputSystem.onDeviceChange-=DeviceChanged;feedback.StopAll();}void OnDestroy(){Time.timeScale=1;}
 public void Dirty(){SetupVersion++;menus.Dirty();}public void Save(){LWS.TruckSports.SportsPrefs.SetString(SetupKey,JsonUtility.ToJson(setup));LWS.TruckSports.SportsPrefs.Save();Dirty();}
 public void PresetAI(int count,BowlingMode mode){setup.mode=mode;setup.count=Mathf.Clamp(count,1,mode==BowlingMode.HotSeat?8:4);for(int i=0;i<setup.count;i++){setup.players[i].source=BowlingSource.AI;setup.players[i].pad=null;}Dirty();}
 public bool Assign(int slot,Gamepad pad){if(slot<0||slot>=setup.count||!setup.players[slot].Controller||pad==null||!pad.added||!pad.enabled)return false;var old=setup.players[slot].pad;setup.players[slot].pad=pad;if(!setup.Validate(out _)){setup.players[slot].pad=old;return false;}if(setup.mode==BowlingMode.HotSeat&&setup.sharedHotSeat&&setup.players[slot].source==BowlingSource.WholeController)for(int i=0;i<setup.count;i++)if(setup.players[i].source==BowlingSource.WholeController)setup.players[i].pad=pad;Gate();Dirty();return true;}
 public void Unassign(int slot){setup.players[slot].pad=null;Gate();Dirty();}public void CycleSource(int slot){var p=setup.players[slot];p.source=(BowlingSource)(((int)p.source+1)%5);p.pad=null;Save();}
 public bool StartMatch(){if(!DevicesReady){menus.Show(BowlingScreen.Join);return false;}Save();InMatch=true;Finished=Paused=false;handoff=false;ActiveSlot=ModalOwner=0;Winners=Array.Empty<int>();Time.timeScale=1;foreach(var p in setup.players){p.score=new BowlingScore();p.released=false;}foreach(var lane in lanes)lane.truck.Clear();Layout();menus.Show(BowlingScreen.Play);if(setup.mode==BowlingMode.Simultaneous){for(int i=0;i<setup.count;i++)lanes[i].StartLane(i);}else StartHotSeat();Gate();return true;}
 void StartHotSeat(){var p=setup.players[ActiveSlot];lanes[0].StartLane(ActiveSlot,true);if(p.source!=BowlingSource.AI&&setup.sharedHotSeat){handoff=true;Gate();menus.Show(BowlingScreen.Handoff);}else{handoff=false;menus.Show(BowlingScreen.Play);}menus.Dirty();}
 public void Handoff(){if(!handoff||!MenuConfirm())return;handoff=false;menus.Show(BowlingScreen.Play);Gate();}
 public void Next(BowlingLane lane,bool frameComplete){if(!InMatch)return;if(setup.mode==BowlingMode.Simultaneous){if(lane.Owner.score.Finished){lane.FinishLane();CheckFinished();}else lane.Continue();return;}
  if(frameComplete){lane.FinishLane();if(CheckFinished())return;for(int i=0;i<setup.count;i++){ActiveSlot=(ActiveSlot+1)%setup.count;if(!setup.players[ActiveSlot].score.Finished)break;}ModalOwner=ActiveSlot;handoffTimer=0;StartHotSeat();}else lane.Continue();
 }
 bool CheckFinished(){for(int i=0;i<setup.count;i++)if(!setup.players[i].score.Finished)return false;if(setup.mode==BowlingMode.Simultaneous)for(int i=0;i<setup.count;i++)if(lanes[i].Phase!=BowlingPhase.Finished)return false;Finished=true;handoff=false;int best=-1,count=0;for(int i=0;i<setup.count;i++){int score=setup.players[i].score.FinalTotal;if(score>best){best=score;count=1;}else if(score==best)count++;}Winners=new int[count];int n=0;for(int i=0;i<setup.count;i++)if(setup.players[i].score.FinalTotal==best)Winners[n++]=i;feedback.StopMotors();feedback.Play(8,0,true);menus.Show(BowlingScreen.Result);return true;}
 public void BindLaneCollision(BowlingLane source){foreach(var other in lanes)if(other!=source){source.truck.IgnorePins(other.pins,true);var a=source.truck.GetComponentsInChildren<Collider>(true);var b=other.truck.GetComponentsInChildren<Collider>(true);foreach(var x in a)foreach(var y in b)Physics.IgnoreCollision(x,y,true);foreach(var x in source.pins)foreach(var y in other.pins)Physics.IgnoreCollision(x.GetComponent<Collider>(),y.GetComponent<Collider>(),true);}}
 public void Layout(){int views=InMatch&&setup.mode==BowlingMode.Simultaneous?setup.count:1;for(int i=0;i<4;i++){lanes[i].cab.view.enabled=i<views;Rect rect;if(views==1)rect=new Rect(0,0,1,1);else if(views==2)rect=new Rect(0,i==0?.5f:0,1,.5f);else if(views==3&&i==0)rect=new Rect(0,.5f,1,.5f);else if(views==3)rect=new Rect(i==1?0:.5f,0,.5f,.5f);else rect=new Rect(i%2*.5f,i<2?.5f:0,.5f,.5f);lanes[i].cab.view.rect=rect;menus.LayoutView(i,rect,i<views);}}
 public void Gate(){foreach(var p in setup.players)p.released=false;foreach(var l in lanes)l.truck.Stop();menuReleased=false;menuGateFrame=Time.frameCount;}
 bool Neutral(int slot){var p=setup.players[slot];if(p.source==BowlingSource.AI)return true;if(!Ready(slot))return false;if(p.source==BowlingSource.Keyboard)return !SportsDeviceInput.KeyHeld(Keys(slot).forward)&&!SportsDeviceInput.KeyHeld(Keys(slot).back)&&!SportsDeviceInput.KeyHeld(Keys(slot).left)&&!SportsDeviceInput.KeyHeld(Keys(slot).right)&&!SportsDeviceInput.KeyHeld(Key.Enter)&&!SportsDeviceInput.KeyHeld(Key.Space);return Drive(slot).sqrMagnitude<.01f&&!p.pad.buttonSouth.isPressed&&!p.pad.startButton.isPressed;}
 public Vector2 Drive(int slot){var p=setup.players[slot];if(p.source==BowlingSource.Keyboard)return new Vector2((SportsDeviceInput.KeyHeld(Keys(slot).right)?1:0)-(SportsDeviceInput.KeyHeld(Keys(slot).left)?1:0),(SportsDeviceInput.KeyHeld(Keys(slot).forward)?1:0)-(SportsDeviceInput.KeyHeld(Keys(slot).back)?1:0));if(!Ready(slot)||p.source==BowlingSource.AI)return Vector2.zero;if(p.source==BowlingSource.LeftStick||p.source==BowlingSource.RightStick){var v=p.source==BowlingSource.LeftStick?p.pad.leftStick.ReadValue():p.pad.rightStick.ReadValue();return new Vector2(Mathf.Abs(v.x)<.16f?0:v.x,Mathf.Abs(v.y)<.16f?0:v.y);}return new Vector2(p.pad.leftStick.x.ReadValue(),p.pad.rightTrigger.ReadValue()-p.pad.leftTrigger.ReadValue());}
 public bool MenuConfirm(){if(!InMatch||Finished)return true;if(!menuReleased)return false;int slot=setup.mode==BowlingMode.HotSeat?ActiveSlot:ModalOwner;var p=setup.players[slot];if(Mouse.current!=null&&Mouse.current.leftButton.wasReleasedThisFrame)return true;if(p.source==BowlingSource.AI||p.source==BowlingSource.Keyboard||menus.Screen==BowlingScreen.Disconnect)return SportsDeviceInput.KeyDown(Key.Enter)||SportsDeviceInput.KeyDown(Key.Space)||(p.pad!=null&&p.pad.added&&p.pad.enabled&&p.pad.buttonSouth.wasPressedThisFrame);return p.pad!=null&&p.pad.added&&p.pad.buttonSouth.wasPressedThisFrame;}
 public void Pause(int owner=0,bool disconnected=false){if(!InMatch||Finished)return;ModalOwner=Mathf.Clamp(owner,0,setup.count-1);Paused=true;Time.timeScale=0;Gate();feedback.StopAll();foreach(var lane in lanes){lane.PauseMotion(true);lane.truck.engine.Stop();lane.truck.skid.Stop();}menus.Show(disconnected?BowlingScreen.Disconnect:BowlingScreen.Pause);}
 public void Resume(){if(!DevicesReady){Pause(ModalOwner,true);return;}Paused=false;Time.timeScale=1;foreach(var lane in lanes)lane.PauseMotion(false);Gate();menus.Show(handoff?BowlingScreen.Handoff:BowlingScreen.Play);}
 public void ChangeSetup(){Paused=false;InMatch=false;handoff=false;Time.timeScale=1;foreach(var lane in lanes)lane.FinishLane();feedback.StopAll();Layout();menus.Show(BowlingScreen.Setup);}
 void DeviceChanged(InputDevice device,InputDeviceChange change){Dirty();if(!InMatch||Finished)return;for(int i=0;i<setup.count;i++)if(setup.players[i].Controller&&setup.players[i].pad==device){input.Forget((Gamepad)device);Gate();if(change==InputDeviceChange.Removed||change==InputDeviceChange.Disconnected||change==InputDeviceChange.Disabled)Pause(i,true);break;}}
 void Update(){input.Sample();if(menus.Screen==BowlingScreen.Join||menus.Screen==BowlingScreen.Disconnect)foreach(var pad in Gamepad.all)if(input.Down(pad,2))for(int i=0;i<setup.count;i++)if(setup.players[i].Controller&&!Ready(i)&&Assign(i,pad)){if(setup.players[i].source==BowlingSource.WholeController)break;}
  if(InMatch&&!menuReleased&&Time.frameCount>menuGateFrame){bool neutral=!SportsDeviceInput.KeyHeld(Key.Enter)&&!SportsDeviceInput.KeyHeld(Key.Space)&&(Mouse.current==null||!Mouse.current.leftButton.isPressed&&!Mouse.current.leftButton.wasReleasedThisFrame);int owner=setup.mode==BowlingMode.HotSeat?ActiveSlot:ModalOwner;neutral&=Neutral(owner);if(setup.players[owner].Controller&&setup.players[owner].pad!=null&&setup.players[owner].pad.added&&setup.players[owner].pad.enabled)neutral&=setup.players[owner].pad.leftStick.ReadValue().magnitude<.16f&&setup.players[owner].pad.rightStick.ReadValue().magnitude<.16f;foreach(var pad in Gamepad.all)neutral&=!pad.buttonSouth.isPressed;if(neutral){menuReleased=true;if(menus.Screen==BowlingScreen.Join||menus.Screen==BowlingScreen.Disconnect)menus.SelectPrimary();}}
  if(!InMatch||Finished)return;if(SportsDeviceInput.KeyDown(Key.Escape)){if(Paused)Resume();else if(menus.Screen==BowlingScreen.Play||menus.Screen==BowlingScreen.Handoff)Pause(setup.mode==BowlingMode.HotSeat?ActiveSlot:0);return;}
  for(int i=0;i<setup.count;i++){if(setup.mode==BowlingMode.HotSeat&&i!=ActiveSlot)continue;var p=setup.players[i];if(p.Controller&&p.pad!=null&&input.Down(p.pad,4)){if(Paused)Resume();else Pause(i);return;}}
  if(SportsDeviceInput.KeyDown(Key.Tab)&&menus.Screen==BowlingScreen.Play){Pause(setup.mode==BowlingMode.HotSeat?ActiveSlot:0);menus.OpenScorecard();return;}if(handoff&&!Paused){handoffTimer+=Time.deltaTime;if(setup.players[ActiveSlot].source==BowlingSource.AI){handoff=false;menus.Show(BowlingScreen.Play);}else if(SportsDeviceInput.KeyDown(Key.Enter)||SportsDeviceInput.KeyDown(Key.Space)){Handoff();}else if(setup.players[ActiveSlot].pad!=null&&setup.players[ActiveSlot].pad.buttonSouth.wasPressedThisFrame)Handoff();}
  if(Paused||handoff||menus.Screen!=BowlingScreen.Play)return;for(int i=0;i<(setup.mode==BowlingMode.HotSeat?1:setup.count);i++){var lane=lanes[i];if(!lane.Driving||lane.Owner.source==BowlingSource.AI)continue;var p=lane.Owner;if(!Ready(lane.ownerSlot)){Pause(lane.ownerSlot,true);return;}if(!p.released){lane.truck.Stop();if(Neutral(lane.ownerSlot))p.released=true;continue;}lane.truck.Control(Drive(lane.ownerSlot));}
 }
 public bool DeliveryAllowed=>!Paused&&!handoff&&menus.Screen==BowlingScreen.Play;

}
}